// Benchmark boilerplate generated by Benchmark

import Benchmark
import SolidFont
import SolidFontBenchmarkSupport

let benchmarks: @Sendable () -> Void = {
  let configuration = Benchmark.Configuration(
    metrics: [.wallClock, .cpuTotal, .throughput, .mallocCountTotal],
    warmupIterations: 3,
    scalingFactor: .one,
    maxDuration: .seconds(5),
    maxIterations: 100
  )

  Benchmark("CFF1 Parse", configuration: configuration) { benchmark in
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      blackHole(try! CompactFontCollection(data: FontBenchmarkFixtures.compactFont))
    }
  }

  Benchmark("TTC Directory Parse", configuration: configuration) { benchmark in
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      blackHole(try! SFNTCollection(data: FontBenchmarkFixtures.fontCollection))
    }
  }

  Benchmark("1,000 Type 1 CharStrings", configuration: configuration) { benchmark in
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      for _ in 0..<1_000 {
        blackHole(try! FontCharStringDecoder.decode(
          FontBenchmarkFixtures.type1CharString,
          dialect: .type1
        ))
      }
    }
  }

  Benchmark("1,000 Type 2 CharStrings", configuration: configuration) { benchmark in
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      for _ in 0..<1_000 {
        blackHole(try! FontCharStringDecoder.decode(
          FontBenchmarkFixtures.type2CharString,
          dialect: .type2
        ))
      }
    }
  }
}
